#include <future>
#include <iostream>
#include <thread>

void calcular(std::promise<int> p) {          // recibe la promesa (se mueve, no se copia)
    int resultado = 6 * 7;                    // trabajo "pesado"
    p.set_value(resultado);                   // cumple la promesa: envía el valor
}

int main() {
    std::promise<int> p;                      // extremo que ESCRIBE
    std::future<int> f = p.get_future();      // extremo que LEE (se obtiene una sola vez)

    std::thread t(calcular, std::move(p));    // promise no se puede copiar: se mueve

    std::cout << "esperando...\n";
    int v = f.get();                          // bloquea hasta que haya valor; solo 1 vez
    std::cout << "resultado: " << v << '\n';  // 42

    t.join();
}

#include <future>
#include <iostream>

int cuadrado(int x) { return x * x; }

int main() {
    // launch::async: se ejecuta YA, en un hilo nuevo (paralelo a main).
    std::future<int> a = std::async(std::launch::async, cuadrado, 5);

    // launch::deferred: NO crea hilo. Se ejecuta en el hilo que llame a get(),
    // recién en ese momento (evaluación perezosa).
    std::future<int> d = std::async(std::launch::deferred, cuadrado, 6);

    // Sin política: la implementación elige async o deferred.
    std::future<int> x = std::async(cuadrado, 7);

    std::cout << a.get() << '\n';   // 25 (probablemente ya estaba calculado)
    std::cout << d.get() << '\n';   // 36 (se calcula AHORA, en el hilo de main)
    std::cout << x.get() << '\n';   // 49
}

